"""Pure validation functions: Luhn, network detection, expiry, CVV, amount, currency."""
import re
import hashlib
import datetime
import calendar

ID_RE = re.compile(r"^[A-Za-z0-9_\-]{1,128}$")


def _utcnow_naive():
    """Return a timezone-naive UTC datetime without using the deprecated utcnow()."""
    return datetime.datetime.now(datetime.timezone.utc).replace(tzinfo=None)


def luhn_check(pan):
    if not pan.isdigit():
        return False
    digits = [int(d) for d in pan]
    checksum = 0
    parity = len(digits) % 2
    for i, d in enumerate(digits):
        if i % 2 == parity:
            d *= 2
            if d > 9:
                d -= 9
        checksum += d
    return checksum % 10 == 0


def detect_network(pan):
    if re.match(r"^4", pan):
        return "visa"
    if re.match(r"^(5[1-5]|2[2-7])", pan):
        return "mastercard"
    if re.match(r"^3[47]", pan):
        return "amex"
    if re.match(r"^(6011|65|64[4-9])", pan):
        return "discover"
    return "unknown"


def cvv_length_for_network(network):
    return 4 if network == "amex" else 3


def validate_cvv(cvv, network):
    return cvv.isdigit() and len(cvv) == cvv_length_for_network(network)


def validate_expiry(month, year, now=None):
    now = now or _utcnow_naive()
    last_day = calendar.monthrange(year, month)[1]
    expiry = datetime.datetime(year, month, last_day, 23, 59, 59)
    return expiry >= now


def validate_amount(amount_cents, min_cents, max_cents):
    return isinstance(amount_cents, int) and min_cents <= amount_cents <= max_cents


def validate_currency(code, allowed):
    return code in allowed


def mask_pan(pan):
    """Mask a PAN keeping the first 6 and last 4 digits visible.

    The middle segment is rendered with asterisks whose count is
    ``len(pan) - 9`` (for pans of at least 10 characters), matching the
    service's documented masking convention.
    """
    if len(pan) < 10:
        return "*" * len(pan)
    star_count = max(len(pan) - 9, 0)
    return pan[:6] + ("*" * star_count) + pan[-4:]


def hash_token(pan):
    return hashlib.sha256(pan.encode("utf-8")).hexdigest()


def sanitize_payload(payload):
    """Strict type/length/charset checks on inbound fields. Raises ValueError."""
    tx = {}

    card_number = payload.get("card_number")
    if not isinstance(card_number, str) or not (12 <= len(card_number) <= 19) or not card_number.isdigit():
        raise ValueError("invalid card_number field")
    tx["card_number"] = card_number

    cvv = payload.get("cvv")
    if not isinstance(cvv, str) or not (3 <= len(cvv) <= 4) or not cvv.isdigit():
        raise ValueError("invalid cvv field")
    tx["cvv"] = cvv

    month = payload.get("expiry_month")
    year = payload.get("expiry_year")
    if not isinstance(month, int) or isinstance(month, bool) or not (1 <= month <= 12):
        raise ValueError("invalid expiry_month field")
    if not isinstance(year, int) or isinstance(year, bool) or not (2000 <= year <= 2100):
        raise ValueError("invalid expiry_year field")
    tx["expiry_month"] = month
    tx["expiry_year"] = year

    amount = payload.get("amount_cents")
    if not isinstance(amount, int) or isinstance(amount, bool):
        raise ValueError("invalid amount_cents field")
    tx["amount_cents"] = amount

    currency = payload.get("currency")
    if not isinstance(currency, str) or not re.fullmatch(r"[A-Z]{3}", currency):
        raise ValueError("invalid currency field")
    tx["currency"] = currency

    idem = payload.get("idempotency_key")
    if idem is not None:
        if not isinstance(idem, str) or not ID_RE.match(idem):
            raise ValueError("invalid idempotency_key field")
    tx["idempotency_key"] = idem

    txid = payload.get("transaction_id")
    if txid is not None:
        if not isinstance(txid, str) or not ID_RE.match(txid):
            raise ValueError("invalid transaction_id field")
    tx["transaction_id"] = txid

    return tx

"""Business rules engine combining format validation, blacklist and velocity checks."""
import json
import uuid
import datetime

from . import validation

HARD_FAIL_REASONS = {
    "invalid_card_number", "expired_card", "invalid_cvv",
    "invalid_amount", "unsupported_currency", "blacklisted",
}


def _utcnow_naive():
    """Return a timezone-naive UTC datetime without using the deprecated utcnow()."""
    return datetime.datetime.now(datetime.timezone.utc).replace(tzinfo=None)


def process_transaction(payload, config, storage):
    request_id = str(uuid.uuid4())
    try:
        tx = validation.sanitize_payload(payload)
    except ValueError as exc:
        return {"error": "validation_error", "message": str(exc)}, 400

    idempotency_key = tx.get("idempotency_key")
    if idempotency_key:
        cached = storage.get_idempotent(idempotency_key, config.idempotency_ttl_seconds)
        if cached:
            resp_json, status_code = cached
            return json.loads(resp_json), status_code

    pan = tx["card_number"]
    network = validation.detect_network(pan)
    masked = validation.mask_pan(pan)
    token_hash = validation.hash_token(pan)

    reasons = []
    if not validation.luhn_check(pan):
        reasons.append("invalid_card_number")
    if not validation.validate_expiry(tx["expiry_month"], tx["expiry_year"]):
        reasons.append("expired_card")
    if not validation.validate_cvv(tx["cvv"], network):
        reasons.append("invalid_cvv")
    if not validation.validate_amount(tx["amount_cents"], config.min_amount_cents, config.max_amount_cents):
        reasons.append("invalid_amount")
    if not validation.validate_currency(tx["currency"], config.allowed_currencies):
        reasons.append("unsupported_currency")
    if storage.is_blacklisted(token_hash):
        reasons.append("blacklisted")

    hard_fail = any(r in HARD_FAIL_REASONS for r in reasons)

    limit_reasons = []
    if not hard_fail:
        now = _utcnow_naive()
        daily_key = "D:" + now.strftime("%Y-%m-%d")
        monthly_key = "M:" + now.strftime("%Y-%m")
        daily_amount, _ = storage.get_velocity(token_hash, daily_key)
        monthly_amount, _ = storage.get_velocity(token_hash, monthly_key)
        amount = tx["amount_cents"]
        if daily_amount + amount > config.daily_limit_cents:
            limit_reasons.append("daily_limit_exceeded")
        if monthly_amount + amount > config.monthly_limit_cents:
            limit_reasons.append("monthly_limit_exceeded")
        storage.add_velocity(token_hash, daily_key, amount)
        storage.add_velocity(token_hash, monthly_key, amount)

    all_reasons = reasons + limit_reasons
    if hard_fail:
        status = "rejected"
    elif limit_reasons:
        status = "flagged"
    else:
        status = "approved"

    transaction_id = tx.get("transaction_id") or request_id
    response = {
        "transaction_id": transaction_id,
        "status": status,
        "reasons": all_reasons,
        "card_network": network,
        "masked_pan": masked,
        "validated_at": _utcnow_naive().isoformat() + "Z",
    }

    if idempotency_key:
        storage.put_idempotent(idempotency_key, json.dumps(response), 200)

    storage.write_audit(request_id, token_hash, masked, status, all_reasons,
                         tx["amount_cents"], tx["currency"])

    return response, 200

"""Unit tests for the pure validation functions."""
import unittest
import datetime

from cardvalidator import validation


class ValidationTests(unittest.TestCase):
    def test_luhn_valid(self):
        self.assertTrue(validation.luhn_check("4111111111111111"))

    def test_luhn_invalid(self):
        self.assertFalse(validation.luhn_check("4111111111111112"))

    def test_detect_network(self):
        self.assertEqual(validation.detect_network("4111111111111111"), "visa")
        self.assertEqual(validation.detect_network("5500000000000004"), "mastercard")
        self.assertEqual(validation.detect_network("378282246310005"), "amex")
        self.assertEqual(validation.detect_network("6011000000000004"), "discover")
        self.assertEqual(validation.detect_network("9999999999999999"), "unknown")

    def test_cvv_length(self):
        self.assertTrue(validation.validate_cvv("123", "visa"))
        self.assertFalse(validation.validate_cvv("12", "visa"))
        self.assertTrue(validation.validate_cvv("1234", "amex"))
        self.assertFalse(validation.validate_cvv("123", "amex"))

    def test_expiry(self):
        now = datetime.datetime(2024, 6, 15)
        self.assertTrue(validation.validate_expiry(6, 2024, now=now))
        self.assertFalse(validation.validate_expiry(5, 2024, now=now))

    def test_amount_bounds(self):
        self.assertTrue(validation.validate_amount(100, 1, 1000))
        self.assertFalse(validation.validate_amount(0, 1, 1000))
        self.assertFalse(validation.validate_amount(1001, 1, 1000))

    def test_currency(self):
        self.assertTrue(validation.validate_currency("USD", {"USD", "EUR"}))
        self.assertFalse(validation.validate_currency("XXX", {"USD", "EUR"}))

    def test_mask_pan(self):
        self.assertEqual(validation.mask_pan("4111111111111111"), "411111*******1111")

    def test_sanitize_payload_valid(self):
        payload = {
            "card_number": "4111111111111111", "cvv": "123",
            "expiry_month": 12, "expiry_year": 2099,
            "amount_cents": 500, "currency": "USD",
        }
        tx = validation.sanitize_payload(payload)
        self.assertEqual(tx["card_number"], "4111111111111111")

    def test_sanitize_payload_invalid(self):
        with self.assertRaises(ValueError):
            validation.sanitize_payload({"card_number": "abc"})


if __name__ == "__main__":
    unittest.main()
